import 'package:flutter/material.dart';

/// Domain types for the MarketGO Onboarder (field onboarding) app.
///
/// Onboarders create vendor & rider accounts out in the field and act as the
/// account officer for every account they onboard. Commission:
///  - [VendorRecord.commissionRate] % of the commission the app earns from the
///    vendor's orders,
///  - a share of the app commission generated by vendors & riders onboarded,
///  - a share of the deliveries driven by onboarded riders.

enum OnboardStatus { pending, active, suspended }

OnboardStatus onboardStatusFromName(String name) {
  switch (name.toLowerCase()) {
    case 'active':
      return OnboardStatus.active;
    case 'suspended':
      return OnboardStatus.suspended;
    default:
      return OnboardStatus.pending;
  }
}

String onboardStatusName(OnboardStatus status) {
  switch (status) {
    case OnboardStatus.active:
      return 'Active';
    case OnboardStatus.pending:
      return 'Pending';
    case OnboardStatus.suspended:
      return 'Suspended';
  }
}

Color onboardStatusColor(OnboardStatus status) {
  switch (status) {
    case OnboardStatus.active:
      return const Color(0xFF16A34A);
    case OnboardStatus.pending:
      return const Color(0xFFD97706);
    case OnboardStatus.suspended:
      return const Color(0xFFDC2626);
  }
}

