/// A single line in a commission breakdown report.
class CommissionDetailLine {
  final int orderId;
  final double orderTotal;
  final double deliveryFee;
  final double serviceFee;
  final double taxAmount;
  final double platformRate;
  final double commissionRate;
  final double shareRate;
  final double onboarderCut;
  final DateTime date;

  const CommissionDetailLine({
    required this.orderId,
    required this.orderTotal,
    required this.deliveryFee,
    required this.serviceFee,
    required this.taxAmount,
    required this.platformRate,
    required this.commissionRate,
    required this.shareRate,
    required this.onboarderCut,
    required this.date,
  });

  factory CommissionDetailLine.fromJson(Map<String, dynamic> j) =>
      CommissionDetailLine(
        orderId: j['order_id'] ?? 0,
        orderTotal: (j['order_total'] ?? 0).toDouble(),
        deliveryFee: (j['delivery_fee'] ?? 0).toDouble(),
        serviceFee: (j['service_fee'] ?? 0).toDouble(),
        taxAmount: (j['tax_amount'] ?? 0).toDouble(),
        platformRate: (j['platform_rate'] ?? 0).toDouble(),
        commissionRate: (j['commission_rate'] ?? 0).toDouble(),
        shareRate: (j['share_rate'] ?? 0).toDouble(),
        onboarderCut: (j['onboarder_cut'] ?? 0).toDouble(),
        date: DateTime.tryParse(j['date'] ?? '') ?? DateTime.now(),
      );
}

/// Full commission breakdown for a specific vendor.
class VendorCommissionDetail {
  final int vendorId;
  final String vendorName;
  final String storeName;
  final double commissionRate;
  final int totalOrders;
  final double totalEarnings;
  final List<CommissionDetailLine> lines;

  const VendorCommissionDetail({
    required this.vendorId,
    required this.vendorName,
    required this.storeName,
    required this.commissionRate,
    required this.totalOrders,
    required this.totalEarnings,
    required this.lines,
  });

  factory VendorCommissionDetail.fromJson(Map<String, dynamic> j) =>
      VendorCommissionDetail(
        vendorId: j['vendor_id'] ?? 0,
        vendorName: j['vendor_name'] ?? '',
        storeName: j['store_name'] ?? '',
        commissionRate: (j['commission_rate'] ?? 0).toDouble(),
        totalOrders: j['total_orders'] ?? 0,
        totalEarnings: (j['total_earnings'] ?? 0).toDouble(),
        lines: (j['lines'] as List<dynamic>? ?? [])
            .map((l) => CommissionDetailLine.fromJson(l))
            .toList(),
      );
}

